\label{proposition:vesentini}
    Let $\mathcal{A}$ be a complex Banach algebra. Let $\Omega\subseteq\mathbb{C}$ be a connected open set and let $F \colon \Omega \to \mathcal{A}$ be holomorphic. Then the function
    \begin{align*}
        R \colon \Omega \to [-\infty, \infty), \quad R(z) \coloneqq \log(\mathrm{r}(F(z)))
    \end{align*}
    is subharmonic, where we use the convention $\log 0 = -\infty$.

Fix $z_0 \in \Omega$ and $\mu \in \sigma(F(z_0)) \cap \mathbb{T}$ and consider the function
    \begin{align*}
        G \colon \Omega \to \mathcal{A}, \qquad G(z) \coloneqq \frac{1 + \overline{\mu} F(z)}{2}.
    \end{align*}
    Then the spectral mapping theorem (see \cite[Theorem~10.28(b)]{Rudin1991}) yields
    \begin{align*}
        \sigma(G(z)) = \set[\bigg]{\frac{1+\overline{\mu}\lambda}{2} : \lambda \in \sigma(F(z))} \subseteq \overline{\mathbb{D}}.
    \end{align*}
    Thus, $\mathrm{r}(G(z)) \leq 1$ for all $z \in \Omega$ and $\mathrm{r}(G(z_0))=1$. As $G$ is holomorphic, Proposition~\ref{proposition:vesentini} implies that the function
    \begin{align*}
        R \colon \Omega \to [-\infty, \infty), \quad R(z) \coloneqq \log(\mathrm{r}(G(z)))
    \end{align*}
    is subharmonic. Moreover, $R(z) \leq 0$ for all $z \in \Omega$ and $R(z_0) = 0$. Therefore, it follows from the maximum principle for subharmonic functions (see \cite[Theorem~2.3.1(i)]{Ransford1995}) that $R(z) = 0$ and thus $\mathrm{r}(G(z)) = 1$ for all $z \in \Omega$. As $\sigma(G(z))$ is compact, there exists $\lambda \in \sigma(F(z))$ such that $\abs{1 + \overline \mu \lambda} = 2$. Since $\abs \lambda \leq 1$, the equality in the triangle inequality implies $\abs \lambda = 1$ and $\lambda = \mu$. Thus, $\mu \in \sigma(F(z)) \cap \mathbb{T}$ for all $z \in \Omega$, which shows the claim.

\label{theorem:peripheral-domination}
    Let $S$ and $T$ be positive operators on a complex Banach lattice $E$ such that $0 \leq S \leq T$ and $\mathrm{r}(T) = 1$. Then one has
    \begin{align*}
        \sigma(S + \mu (T - S)) \cap \mathbb{T} = \sigma(S) \cap \mathbb{T} \subseteq \sigma(T) \cap \mathbb{T}
    \end{align*}
    for all $\mu \in \mathbb{D}$.

Consider the holomorphic function
    \begin{align*}
        F \colon \mathbb{D} \to \mathcal{L}(E), \quad F(\mu) \coloneqq S + \mu (T - S).
    \end{align*}
    Then one has
    \begin{align*}
        \abs{F(\mu) x} \leq (S + \abs \mu (T - S)) \abs x \leq T\abs x
    \end{align*}
    for all $\mu \in \mathbb{D}$ and $x \in E$. Iterating the inequality yields $\abs{F(\mu)^n x} \leq T^n \abs{x}$ for all $n \in \mathbb{N}$. Thus, $\norm{F(\mu)^n} \leq \norm{T^n}$ for all $n \in \mathbb{N}$, which implies $\mathrm{r}(F(\mu)) \leq \mathrm{r}(T) = 1$ by Gelfand's formula. Now it follows from Proposition~\ref{proposition:peripheral-rigidity} that
    \begin{align*}
        \sigma(S + \mu (T - S)) \cap \mathbb{T} = \sigma(S) \cap \mathbb{T}
    \end{align*}
    for all $\mu \in \mathbb{D}$. To prove the inclusion, fix $\lambda \in \sigma(S) \cap \mathbb{T}$. Then $\lambda I - F(t)$ is not invertible for any $0 \leq t < 1$. Since $F(t) \to T$ in operator norm as $t \to 1$ and the set of invertible operators is open, $\lambda I - T$ is not invertible either. Thus, $\lambda \in \sigma(T) \cap \mathbb{T}$.

\label{corollary:raebiger-wolff}
    Let $S$ and $T$ be positive operators on a complex Banach lattice $E$ such that $0 \leq S \leq T$ and $\mathrm{r}(S) = \mathrm{r}(T)$. Then one has the inclusion
    \begin{align*}
        \sigma(S) \cap \mathrm{r}(S)\mathbb{T} \subseteq \sigma(T) \cap \mathrm{r}(T) \mathbb{T}.
    \end{align*}

\label{remark:rabiger-wolff}
    Räbiger and Wolff showed the above corollary under the additional assumption that $T$ is \emph{$(G)$-solvable} (see \cite[Corollary~1.5]{Rabiger1997}), i.e., there exist finitely many closed $T$-invariant ideals $\set{0} = I_0 \subseteq I_1 \subseteq I_2 \subseteq \ldots \subseteq I_n = E$, $n \in \mathbb{N}$, such that the operators $T_k$ induced by $T$ on $I_k/I_{k - 1}$, $1 \leq k \leq n$, satisfy the \emph{growth condition $(G)$}, given by
    \begin{align*}
        \limsup_{\lambda \downarrow \mathrm{r}(T_k)} \norm{(\lambda - \mathrm{r}(T_k)) R(\lambda, T_k)} < \infty.
    \end{align*}
    Depending on the specific reference, the notion of $(G)$-solvability is also referred to as \emph{Abel solvability}, whereas the growth condition $(G)$ is referred to as \emph{Abel boundedness}.

    What is rather interesting in the context of the present paper is that the cyclicity conjecture was also known to be true for $(G)$-solvable operators (see \cite[Theorem~4.9]{Lotz1968}) by a classical theorem of Lotz. In Appendix~\ref{section:g-solvable-case}, we will show that Lotz' theorem is indeed a consequence of the theorem of Räbiger and Wolff.

\label{example:irrational-shift}
    Let $E \coloneqq C(\mathbb{T})$ and fix $\lambda \in \mathbb{T}$ which is not a root of unity. Consider the irrational shift
    \begin{align*}
        T \colon E \to E, \quad T f(z) \coloneqq f(\lambda z).
    \end{align*}
    Then $T$ is a positive invertible isometry and thus $\sigma(T) \subseteq \mathbb{T}$. Moreover, the functions $z \mapsto z^k$ are eigenvectors for the eigenvalues $\lambda^k$, $k \in \mathbb{Z}$. Since these eigenvalues are dense in $\mathbb{T}$, one has $\sigma(T) = \mathbb{T}$. We show that $T$ does not admit a minorant that is rotationally self-similar to it with respect to $-1$. For this, we just need the following two insights:
    \begin{enumerate}[\upshape (a)]
        \item Each positive operator $S$ on $E$ with $S \leq T$ and $\mathrm{r}(S) = 1$ coincides with $T$.
        \item There is no torsion operator $U$ such that $T U = -U T$.
    \end{enumerate}
    (a): First observe that every positive operator $S$ on $E$ with $S \leq T$ is of the form $S = M_a T$ for some $a \in C(\mathbb{T})$ with $0 \leq a \leq 1$, where $M_a f \coloneqq af$. Indeed, one has $0 \leq Sf(z) \leq Tf(z) = f(\lambda z)$ for each $f \geq 0$ and $z \in \mathbb{T}$. Thus, the positive functional $f \mapsto Sf(z)$ is dominated by evaluation at $\lambda z$ and is therefore a scalar multiple of that evaluation. Hence, for each $z \in \mathbb{T}$ there exists $a(z) \in [0, 1]$ such that $S f(z) = a(z)f(\lambda z)$. For the special case $f = \operatorname{\mathbbm{1}}$, one gets that $a = S \operatorname{\mathbbm{1}}$, so $a \in C(\mathbb{T})$.

    We next show that $\mathrm{r}(S) = 1$ implies $a = \operatorname{\mathbbm{1}}$ and thus $S = T$. Arguing by contraposition, suppose that $a \neq \operatorname{\mathbbm{1}}$. Then there exist a non-empty open set $O \subseteq \mathbb{T}$ and a constant $c < 1$ such that $a \leq c$ on $O$. Since the rotation $z \mapsto \lambda z$ is minimal, one has $N \in \mathbb{N}$ such that $\mathbb{T} = \bigcup_{n = 0}^{N - 1} \lambda^{-n} O$ (cf.~\cite[Proposition~3.3]{Eisner2015}). Thus, for every $z \in \mathbb{T}$, at least one of the elements $z, \lambda z, \ldots, \lambda^{N-1}z$ is contained in $O$. Consequently,
    \begin{align*}
    S^N \operatorname{\mathbbm{1}}(z)= \prod_{k = 0}^{N - 1} a(\lambda^k z) \leq c < 1
    \end{align*}
    for all $z \in \mathbb{T}$. Hence $\norm{S^N} = \norm{S^N \operatorname{\mathbbm{1}}}_\infty \leq c$ and therefore $\mathrm{r}(S) \leq c^{1/N} < 1$.

    (b): If $Tf=-f$, then $T^2f=f$. Since the rotation $z \mapsto \lambda^2 z$ is minimal, every continuous function fixed by $T^2$ is constant (see \cite[Proposition~3.6 \& Lemma~4.20]{Eisner2015}). Hence $f$ is constant, and $T f = -f$ implies $f = 0$, which shows that $-1 \notin \sigma_p(T)$. Now suppose that there were a torsion operator $U$ such that $T U = -U T$. Then $T U \operatorname{\mathbbm{1}} = -U T \operatorname{\mathbbm{1}} = - U \operatorname{\mathbbm{1}}$. On the other hand, $\abs{U \operatorname{\mathbbm{1}}} = \operatorname{\mathbbm{1}}$, so $U \operatorname{\mathbbm{1}} \neq 0$. Thus $-1 \in \sigma_p(T)$, which is clearly a contradiction.

To motivate the following construction, note that one can characterise when an operator admits a rotationally self-similar minorant in the following way: Let $U$ be a torsion operator, $\lambda \in \mathbb{T}$, and consider the operator
    \begin{align*}
        \Psi \colon \mathcal{L}(E) \to \mathcal{L}(E), \quad \Psi(Q) \coloneqq \overline \lambda U^{-1} Q U.
    \end{align*}
    Then $S$ is a rotationally self-similar minorant of some positive operator $T$ with respect to $\lambda$ if and only if $\Psi(S) = S$, i.e., $S$ is a fixed point of $\Psi$. So if such an $S$ does not exist (as in Example~\ref{example:irrational-shift}) and one looks for a sequence $(S_n)_{n \in \mathbb{N}}$ of critical minorants of $T$ with respect to $\lambda$, one might be tempted to iterate $\Psi$ on $T$ to find such a sequence. However, $\Psi(T)$ does not even need to be real in general. On the other hand, the operator $\operatorname{Re}(\Psi(T)) = \frac 1 2 (\Psi(T) + \overline{\Psi(T)})$ is real, but in general not positive. Using that $U$ is a torsion operator, one can show that
    \begin{align*}
        - T \leq \frac 1 2 (\Psi(T) + \overline{\Psi(T)}) \leq T.
    \end{align*}
    So if we take another mean, this time with $T$, then we get that the operator
    \begin{align*}
        \Phi \colon \mathcal{L}(E) \to \mathcal{L}(E), \quad \Phi(Q) \coloneqq \frac{\operatorname{Re}(\Psi(Q)) + Q}{2} = \frac{2Q + \overline\lambda U^{-1} Q U + \lambda U Q U^{-1}}{4}
    \end{align*}
    is indeed positive. Thus, we can iterate $\Phi$ on $T$ without giving up the positivity of its iterates.

Let $0\neq z\in E$ satisfy $Tz=\lambda z$ and set $u\coloneqq\abs z$. By Proposition~\ref{proposition:torsion-operator-construction}, there exists a torsion operator $U$ on $E$ such that $Uu=z$.

Consider the operator
\begin{align*}
    \Phi \colon \mathcal{L}(E) \to \mathcal{L}(E), \quad \Phi(Q) \coloneqq \frac{2Q + \overline\lambda U^{-1} Q U + \lambda U Q U^{-1}}{4}
\end{align*}
and define the sequence $(S_n)_{n \in \mathbb{N}}$ recursively via $S_1 = \Phi(T)$ and $S_{n + 1} = \Phi(S_n)$ for all $n \in \mathbb{N}$. Then Proposition~\ref{proposition:torsion-properties}(i) yields
\begin{align*}
    \Phi(Q) x
    &= \frac{2Qx + \overline\lambda U^{-1} Q Ux + \lambda U Q U^{-1}x}{4} \\
    &= \frac{2Qx + \overline\lambda U^{-1} Q Ux + \overline{\overline\lambda U^{-1} Q Ux}}{4} \\
    &= \frac{Qx + \operatorname{Re}(\overline\lambda U^{-1} Q Ux)}{2}
\end{align*}
for each positive operator $Q$ on $E$ and $x \in E_+$. Since $\abs{\overline \lambda U^{-1} Q U x} \leq Q \abs{Ux} = Qx$, it follows that $0 \leq \Phi(Q) \leq Q$. Thus, it follows inductively that $0 \leq S_{n+1} \leq S_n \leq T$ for all $n \in \mathbb{N}$.

Next, we show that each $S_n$ is a critical minorant of $T$. Since $Tu \geq \abs{Tz} = u$, $Uu=z$, and $Tz=\lambda z$, one has
\begin{align*}
    S_1u = \Phi(T)u = \frac{Tu+\operatorname{Re}(\overline\lambda U^{-1} T U u)}{2} = \frac{Tu + u}{2} \geq u.
\end{align*}
Thus $S_1^m u\geq u$ for every $m\in\mathbb{N}$, so $\mathrm{r}(S_1)\geq1$. On the other hand, $0\leq S_1\leq T$ implies $\mathrm{r}(S_1)\leq \mathrm{r}(T)=1$, and hence $\mathrm{r}(S_1)=1$.

Now let $n\geq2$. Since $\Phi$ is positive and $\Phi(Q)\leq Q$ for each $Q\geq0$, one obtains
\begin{align*}
    T - S_n = \sum_{j = 0}^{n - 1} \Phi^j (T - S_1) \leq n (T - S_1).
\end{align*}
Consequently, $S_1 \leq (1-\frac 1 n) T + \frac 1 n S_n \leq T$. Since $\mathrm{r}(S_1)=\mathrm{r}(T)=1$, monotonicity of the spectral radius implies that $\mathrm{r}((1 - \frac 1 n) T + \frac 1 n S_n) = 1$, and Theorem~\ref{theorem:peripheral-domination} yields $\mathrm{r}(S_n)=1$ for all $n \in \mathbb{N}$.

It remains to prove that the sequence $(S_n)_{n \in \mathbb{N}}$ is asymptotically rotationally self-similar. Set
\begin{align*}
    p_{n,k}
    \coloneqq
    4^{-n}\binom{2n}{n+k}
    \qquad (-n\leq k\leq n),
\end{align*}
and set $p_{n,k}\coloneqq0$ otherwise. Consider the invertible isometry $\mathcal{A} \colon \mathcal{L}(E) \to \mathcal{L}(E)$ given by $\mathcal{A}(Q) \coloneqq \overline\lambda U^{-1} Q U$. Since $\Phi = (2I + \mathcal{A} + \mathcal{A}^{-1})/4 = \mathcal{A}^{-1}(I + \mathcal{A})^2/4$, the binomial formula yields
\begin{align*}
    S_n
    =
    \sum_{k\in\mathbb{Z}}
    p_{n,k}\,
    \overline\lambda^{\,k}U^{-k}TU^k.
\end{align*}
Conjugation by $U$, followed by multiplication by $\overline\lambda$, shifts the coefficients by one. Since $U$ is an isometry and $(p_{n,k})_{k\in\mathbb{Z}}$ is symmetric and unimodal with maximum $p_{n,0}$, it follows that
\begin{align*}
    \norm{S_nU-\lambda US_n}
    &=
    \norm{\overline\lambda U^{-1} S_n U - S_n}\\
    &\leq
    \norm T\sum_{k\in\mathbb{Z}}\abs{p_{n,k-1}-p_{n,k}} \leq 2p_{n,0}\norm T =
    \frac{2}{4^n}\binom{2n}{n}\norm T
    \to 0
\end{align*}
as $n \to \infty$. Hence $(S_n)_{n \in \mathbb{N}}$ is asymptotically rotationally self-similar to $T$ with respect to $\lambda$.

Let $(S_n)_{n \in \mathbb{N}}$ be a sequence of minorants that is asymptotically rotationally self-similar to $T$ with respect to $\lambda$ and let $U$ be the corresponding torsion operator. Then $\norm{S_n U - \lambda U S_n} \to 0$ as $n \to \infty$. Since $0 \leq S_n \leq T$, one has $\norm{S_n} \leq \norm T$ for each $n \in \mathbb{N}$, so the operator
    \begin{align*}
        S \colon E^\mathcal{U} \to E^\mathcal{U}, \quad S x^\mathcal{U} \coloneqq (S_n x_n)_\mathcal{U}
    \end{align*}
    is well-defined. Moreover, one clearly has $0 \leq S \leq T^\mathcal{U}$. Note further that $U^\mathcal{U}$ is a torsion operator. The sequence $(S_n U - \lambda U S_n)_{n \in \mathbb{N}}$ is mapped to the zero operator by the ultrapower embedding, so $S U^\mathcal{U} = \lambda U^\mathcal{U} S$. Finally, for every fixed $k \in \mathbb{N}$, one has
    \begin{align*}
        1 \leq \lim_{n \to \mathcal{U}} \norm{S_n^k}^{1 / k} = \norm{S^k}^{1 / k} \leq \norm{T^k}^{1 / k}.
    \end{align*}
    Letting $k \to \infty$, we obtain $\mathrm{r}(S) = 1$ by Gelfand's formula. Thus, $S$ is a minorant that is rotationally self-similar to $T^\mathcal{U}$ with respect to $\lambda$.

(i): By Proposition~\ref{proposition:signum-operator}(iii), $S_z$ vanishes on the band $\{\abs z\}^{\perp}$. Therefore, one has $S_z = S_z P + S_z(I - P) = S_z P$.

(ii): By (i), one has $\abs{S_z x} = \abs{S_z Px} \leq \abs{Px} = P \abs x$ for each $x \in E$. Thus, $S_z$ is regular and, since $E$ is Dedekind complete, its operator modulus exists and satisfies $0 \leq \abs{S_z} \leq P$. In particular, $S_z$ belongs to the ideal centre of $E$.
Moreover,
\begin{align*}
    \abs z = \abs{S_z\overline z} \leq \abs{S_z}\abs z \leq P\abs z = \abs z.
\end{align*}
Hence $\abs{S_z}\abs z=\abs z$. Both $\abs{S_z}$ and $P$ satisfy the three properties in Proposition~\ref{proposition:signum-operator} for the vector $\abs z$, so uniqueness yields $\abs{S_z} = P$. For operators in the ideal centre, the identity
\begin{align*}
    S_z\overline{S_z} = \overline{S_z}S_z = \abs{S_z}^2 = P
\end{align*}
holds (see~\cite[Theorem~3.1~and~Remark~3.2(1)]{deJeu2025}). Moreover, $\abs{\overline{S_z}y} = \abs{S_z\overline y} \leq \abs y$ for every $y \in E$. So, for $x \in \set{\abs z}^{\perp\perp}$, one has
\begin{align*}
\abs x = \abs{Px} = \abs{\overline{S_z} S_z x} \leq \abs{S_z x} \leq \abs x
\end{align*}
and therefore $\abs{S_z x} = \abs x$.

(iii): Conjugating $S_z\overline z = \abs z$ yields $\overline{S_z} z = \abs z$. Thus, the identity established above implies $S_z \abs z = S_z\overline{S_z}z = Pz = z$.

Denote by $S_z$ the signum operator associated with $z$ and by $P$ the band projection onto $\set{\abs z}^{\perp\perp}$. We consider the operator
\begin{align*}
    U \colon E \to E, \qquad U \coloneqq S_z + I-P,
\end{align*}
and show that it has the desired properties.

First, let $x\in E$. By Lemma~\ref{lemma:signum-properties}, one has $S_z = S_zP$ and $\abs{S_z P x} = \abs{Px}$, so $S_z P x\in \set{\abs z}^{\perp\perp}$. Thus, the vectors $S_z P x$ and $(I - P)x$ are disjoint. Hence,
\begin{align*}
    \abs{Ux} = \abs{S_zPx+(I-P)x} = \abs{S_zPx}+\abs{(I-P)x} = \abs{Px}+\abs{(I-P)x} = \abs x.
\end{align*}
Thus, $U$ is a torsion operator. Moreover, since $P \abs z = \abs z$, it follows from Lemma~\ref{lemma:signum-properties} that $U \abs z = S_z \abs z = z$.

\label{lemma:criticality-under-growth}
    Let $T$ be a positive $(G)$-solvable operator on a complex Banach lattice $E$ such that $\mathrm{r}(T)=1$, and let $0 \leq S \leq T$. Suppose that there exist $0 \neq u \in E_+$ and $c \geq 0$ such that
    $Tu \geq u$ and
    \begin{align*}
        (T - S)u \leq c(Tu - u).
    \end{align*}
    Then one has $\mathrm{r}(S)=1$.

First suppose that $T$ satisfies $(G)$. Following the proof of \cite[Theorem~1.4]{Rabiger1997}, consider the continuous lattice seminorm
    \begin{align*}
        p(x) \coloneqq \limsup_{t \downarrow 1}(t - 1)\norm{R(t, T) \abs x}
    \end{align*}
    and the closed ideal $J \coloneqq \ker p$. Since $p(Tx) \leq \norm T p(x)$, the ideal $J$ is $T$-invariant. Moreover, $0 \leq S \leq T$ implies that $J$ is also $S$-invariant.

    Since $Tu \geq u$, one has $(t-1)R(t,T)u \geq u$ for every $t>1$, and hence $p(u) \geq \norm u > 0$. On the other hand, the resolvent identity and $(G)$ yield
    \begin{align*}
        (t - 1)R(t, T)(Tu - u) &= (t - 1)^2 R(t, T)u - (t - 1) u \to 0
    \end{align*}
    as $t \downarrow 1$. Thus $Tu - u \in J$. The assumption $0 \leq (T - S)u \leq c(Tu - u)$ now implies that $(T - S) u \in J$, so $Su - u = Tu - u - (T - S)u \in J$.

    Consequently, the operator $\widetilde S$ induced by $S$ on $E/J$ satisfies $\widetilde S(u + J) = u + J \neq 0$. Therefore,
    \begin{align*}
        1 \leq \mathrm{r}(\widetilde S) \leq \mathrm{r}(S) \leq \mathrm{r}(T) = 1.
    \end{align*}

    Since $T$ is $(G)$-solvable, there exist ideals $\set{0} = I_0 \subseteq I_1 \subseteq \cdots \subseteq I_m = E$. Denote by $T_j$ and $S_j$ the operators induced by $T$ and $S$ on $I_j/I_{j-1}$.

    Choose the least $j \in \set{0, \ldots, m}$ such that $u \in I_j$ and set
    $u_j \coloneqq u + I_{j - 1}$. Then $u_j \neq 0$,
    $T_j u_j \geq u_j$, and
    \begin{align*}
        0 \leq (T_j - S_j) u_j
        \leq c(T_j u_j - u_j).
    \end{align*}
    Moreover, $T_j u_j \geq u_j \neq 0$ implies that $\mathrm{r}(T_j) \geq 1$, while $\mathrm{r}(T_j) \leq \mathrm{r}(T) = 1$. Since $T_j$ satisfies $(G)$, the first part of the proof yields $\mathrm{r}(S_j)=1$. Hence, one obtains $1 = \mathrm{r}(S_j) \leq \mathrm{r}(S) \leq 1$.
